class Solution {
public:
    string thousandSeparator(int n) {
        string result;
        int count = 0;
        do {
            result += char('0' + n % 10);
            n /= 10;
            count++;
            if (count % 3 == 0 && n > 0) {
                result += '.';
            }
        } while (n > 0);
        reverse(result.begin(), result.end());
        return result;
    }
};
